"""Scope gate for delegated service calls."""


class Principal:
    def __init__(self, subject, scopes, delegated_by):
        self.subject = subject
        self.scopes = tuple(scopes)
        self.delegated_by = delegated_by


class Operation:
    def __init__(self, scope, delegation_allowed):
        self.scope = scope
        self.delegation_allowed = delegation_allowed


